import{_ as n,o as a,c as i,a5 as e}from"./chunks/framework.CsGesDJn.js";const d=JSON.parse('{"title":"05 — Content & Task Workflow","description":"","frontmatter":{},"headers":[],"relativePath":"ba/05-content-task-workflow.md","filePath":"ba/05-content-task-workflow.md"}'),o={name:"ba/05-content-task-workflow.md"};function h(r,t,c,l,s,g){return a(),i("div",null,[...t[0]||(t[0]=[e(`<h1 id="_05-—-content-task-workflow" tabindex="-1">05 — Content &amp; Task Workflow <a class="header-anchor" href="#_05-—-content-task-workflow" aria-label="Permalink to &quot;05 — Content &amp; Task Workflow&quot;">​</a></h1><p>&gt; <strong>BA hiện hành 2026-10-18 — FR 3.6.9:</strong> Creator được giao → Manager → một Client active bất kỳ nếu requiresClientApproval. Không QC. Giữ TODO/IN_PROGRESS/IN_REVIEW/FINISHED/CANCELLED và reviewStep riêng. POST dùng <code>/editor</code>, một bản nội dung hiện tại được khóa sửa khi IN_REVIEW; không snapshot/diff nội dung lượt cũ. Reject về IN_PROGRESS; gửi lại lượt mới từ Manager. Creator chỉ thu hồi trước Manager decision. Thiếu Client active thì chặn submit và báo Manager bổ sung, không tự bỏ bước. FINISHED không tự publish. Quy tắc này thay thế phần Approval/QC/ngày đăng dự kiến trong các ghi chú lịch sử bên dưới. <a href="./../feature/content-task-workflow/3-6-9-approval-sequence-creator-manager-client/spec.html">Spec v3 và kế hoạch giai đoạn</a>. Code/API và UI giai đoạn 3–5 đã kiểm thử cô lập; feature gate vẫn tắt, Atlas chưa APPLY và chưa nghiệm thu end-to-end/rollout.</p><p>&gt; <strong>BA mới đã chốt 2026-10-15:</strong> Task chỉ còn TODO / IN_PROGRESS / IN_REVIEW / CANCELLED / FINISHED. Giao việc là metadata, không còn bước DETAIL_IDENTIFIED/ASSIGNED. Phải có mô tả + deadline hợp lệ trước giao; Creator được giao bấm bắt đầu mới IN_PROGRESS; sau đó Manager khóa sửa/giao lại. IN_REVIEW giữ QC → Manager → Client khi được cấu hình; reject về IN_PROGRESS, duyệt lại từ QC nếu có. Approval do thành viên khác triển khai. Autosave on-blur và action list chỉ assignment/deadline/start. Ghi chú mới này thay thế vòng đời Task lịch sử bên dưới; xem <a href="./../feature/content-task-workflow/task-five-state-inline-edit/spec.html">spec mới</a>.</p><p>&gt; <a href="./00-overview.html">&lt;&lt; Về Overview</a></p><p>&gt; <strong>Xác nhận mới nhất 2026-10-14 — FR 3.6.1/2/3 và tích hợp Approval:</strong> tách hạn hoàn thành mọi Task khỏi ngày đăng dự kiến POST; Manager chỉ sửa yêu cầu/giao lại trước lần Creator bắt đầu đầu tiên; đợt này làm khung đầu vào cho 5 loại Task, không làm thay nội dung chuyên biệt. Vẫn cho comment trên COMPLETED/CANCELLED; mention và ảnh JPEG/PNG/WebP, tối đa 5 ảnh × 5 MB/comment. Q13 mới nhất: Client active xem/bình luận mọi Task cùng Workspace, kể cả Task thủ công và cũ; không phân biệt nội bộ/thường. Comment không phụ thuộc requiresClientApproval, cờ này chỉ cấu hình bước Client duyệt kết quả. Resubmit sau reject duyệt lại từ QC nếu có (không có thì Manager), giữ nguyên lịch sử audit. Các đoạn cũ về 3 loại/nhân sự ở bước Identify chỉ là nền lịch sử; chi tiết và câu hỏi còn mở ở <a href="./../feature/content-task-workflow/task-detail-assignment-comments-roadmap.html">roadmap</a>. Người dùng/lead cần thông báo các chủ module liên quan; không tự sửa code của họ.</p><h2 id="_1-nguon-goc-task-trong-backlog" tabindex="-1">1. Nguồn gốc Task trong backlog <a class="header-anchor" href="#_1-nguon-goc-task-trong-backlog" aria-label="Permalink to &quot;1. Nguồn gốc Task trong backlog&quot;">​</a></h2><p><strong>Q13 confirmed 2026-10-14 — thay phần phân quyền Q6/Q9 và quy tắc Q12:</strong> Client active được xem và bình luận mọi Task trong đúng Workspace, kể cả Task Manager tạo thủ công và Task cũ. Không có phân biệt nội bộ/thường hoặc field/default/bộ chọn visibility; Q12 cũ không còn áp dụng. requiresClientApproval=true/false chỉ quyết định chuỗi duyệt kết quả, không quyết định quyền xem/bình luận. Giữ quyền sửa/giao việc/editor theo vai trò; membership/scope và quyền riêng của upload DRAFT vẫn kiểm tra. Không tự sửa dữ liệu legacy; marker start chỉ ảnh hưởng mutation quản lý, không chặn đọc/bình luận.</p><p><strong>Bổ sung Q9–Q11 confirmed 2026-10-14:</strong> Phần phân quyền/default Task Q9 đã được Q13 thay thế; mọi nguồn Task cùng Workspace cho Client active xem/bình luận. Task Campaign đặt hạn trong max(today,start)..end theo múi giờ Workspace; ngày đăng POST không trước dueDate và trong Campaign. Task thủ công không Campaign có hạn từ hôm nay. Notification comment chỉ in-app cho mentions, assignee, QC, Manager; bỏ trùng/tác giả/người không còn quyền, Client chỉ nhận khi mention. Q8 confirmed: Creator bấm Bắt đầu làm mới chuyển ASSIGNED → IN_PROGRESS; mở trang/editor không tính. Dấu mốc lần đầu giữ nguyên sau reject.</p><p>Backlog KHÔNG đóng — có 3 nguồn tạo Task:</p><ol><li><strong>Từ Media Campaign approve</strong> — xem <a href="./04-media-package-campaign.html">04-media-package-campaign.md</a> mục 3.</li><li><strong>Từ Content Request được accept</strong> — xem <a href="./04-media-package-campaign.html">04-media-package-campaign.md</a> mục 4.</li><li><strong>[CONFIRMED 2026-09-14]</strong> Manager tự do thêm Task thủ công vào backlog bất cứ lúc nào — không bắt buộc phải có nguồn gốc từ Campaign hay Content Request (ví dụ sửa bài cũ, họp chuẩn bị, v.v.; theo Q13 Client cùng Workspace vẫn xem/bình luận được)</li></ol><h2 id="_2-vong-đoi-1-task" tabindex="-1">2. Vòng đời 1 Task <a class="header-anchor" href="#_2-vong-đoi-1-task" aria-label="Permalink to &quot;2. Vòng đời 1 Task&quot;">​</a></h2><h3 id="_3-6-1-—-identify-task-detail" tabindex="-1">3.6.1 — Identify Task Detail <a class="header-anchor" href="#_3-6-1-—-identify-task-detail" aria-label="Permalink to &quot;3.6.1 — Identify Task Detail&quot;">​</a></h3><ul><li>Khi Task còn ở backlog (vừa sinh ra từ Campaign), nó chỉ có: tên công việc, tiêu đề, yêu cầu đầu ra — <strong>chưa cụ thể ai làm, làm gì</strong>.</li><li>Manager thêm đầy đủ: người thực hiện, ngày đăng, yêu cầu chi tiết, và <strong>các field khác tùy theo loại công việc</strong> (Post/Livestream/Survey — xem mục 3).</li><li>Role: MANAGER.</li></ul><h3 id="_3-6-2-—-assign-task-to-creator" tabindex="-1">3.6.2 — Assign Task To Creator <a class="header-anchor" href="#_3-6-2-—-assign-task-to-creator" aria-label="Permalink to &quot;3.6.2 — Assign Task To Creator&quot;">​</a></h3><ul><li>Gắn công việc cho Creator active; cần mô tả và dueDate hợp lệ, Task vẫn TODO. Không giao QC. Manager chỉ sửa/giao lại trước lần Creator bắt đầu đầu tiên; reject/withdraw không mở lại quyền này.</li><li>Role: MANAGER.</li></ul><h3 id="_3-6-3-—-add-comments-on-task" tabindex="-1">3.6.3 — Add Comments On Task <a class="header-anchor" href="#_3-6-3-—-add-comments-on-task" aria-label="Permalink to &quot;3.6.3 — Add Comments On Task&quot;">​</a></h3><ul><li>Đưa ra nhận xét, yêu cầu chỉnh sửa trên task.</li><li>Role: CREATOR, CLIENT, MANAGER.</li></ul><h2 id="_3-cac-loai-task-—-dung-chung-khung-workflow" tabindex="-1">3. Các loại Task — dùng chung khung workflow <a class="header-anchor" href="#_3-cac-loai-task-—-dung-chung-khung-workflow" aria-label="Permalink to &quot;3. Các loại Task — dùng chung khung workflow&quot;">​</a></h2><p><strong>Cập nhật 2026-10-18:</strong> ngoài POST/LIVESTREAM/SURVEY, nền Task hiện có EVENT_PLAN và PRESS_RECOMMENDATION. Đợt FR 3.6.9 chỉ tích hợp nội dung POST qua /editor; các loại khác phối hợp chủ module sau, không tự submit/duyệt giả. Mô tả module chuyên biệt bên dưới giữ phạm vi của người phụ trách.</p><p><strong>[CONFIRMED 2026-09-14]</strong> Task có 3 loại nội dung khác nhau, nhưng đều đi qua chung quy trình duyệt (mục 4).</p><h3 id="loai-1-—-post-media-platform-post" tabindex="-1">Loại 1 — Post (Media Platform Post) <a class="header-anchor" href="#loai-1-—-post-media-platform-post" aria-label="Permalink to &quot;Loại 1 — Post (Media Platform Post)&quot;">​</a></h3><ul><li>Viết content, tạo ảnh/video AI, watermark, hashtag — xem chi tiết mục 6, 7.</li></ul><h3 id="loai-2-—-livestream-fr-3-6-22-–-3-6-24" tabindex="-1">Loại 2 — Livestream (FR 3.6.22 – 3.6.24) <a class="header-anchor" href="#loai-2-—-livestream-fr-3-6-22-–-3-6-24" aria-label="Permalink to &quot;Loại 2 — Livestream (FR 3.6.22 – 3.6.24)&quot;">​</a></h3><ul><li><strong>Write Livestream Idea</strong> (3.6.22): điền ý tưởng và mục tiêu hướng tới. Role: MANAGER, CREATOR.</li><li><strong>Write Livestream Script</strong> (3.6.23): viết kịch bản đầy đủ cho 1 phiên livestream. Role: CREATOR.</li><li><strong>Track Livestream Status</strong> (3.6.24): hiển thị tiến độ Live Stream — theo sơ đồ gồm các trạng thái <strong>Pre-live → Live → Post-live → Done/Cancel</strong>. Role: CREATOR.</li><li>Ghi chú bổ sung từ sơ đồ (khu vực &quot;Live Stream&quot; trong Flow diagram — checklist thực tế khi triển khai): <ul><li>Ý tưởng, chiến lược target.</li><li>Kịch bản.</li><li>Tính toán rủi ro, những cái không lường trước được.</li><li>Quay phim, chụp, setup chuẩn bị.</li><li>Quay Livestream, quay máy ảnh → BTS (behind the scenes) có source đẹp trên livestream được quay bằng camera.</li><li>Có người đảm sát, người diễn viên.</li><li>Trong livestream sẽ có retouch lại các source cắt cam và từ video edit để chạy hook (dùng để đưa lên mới các bạn sắp tiếp).</li></ul></li></ul><h3 id="loai-3-—-survey-form-fr-3-6-25-–-3-6-27" tabindex="-1">Loại 3 — Survey/Form (FR 3.6.25 – 3.6.27) <a class="header-anchor" href="#loai-3-—-survey-form-fr-3-6-25-–-3-6-27" aria-label="Permalink to &quot;Loại 3 — Survey/Form (FR 3.6.25 – 3.6.27)&quot;">​</a></h3><ul><li><strong>Create Survey</strong> (3.6.25): tạo khảo sát cho workshop. Role: CREATOR.</li><li><strong>View Survey Analysis</strong> (3.6.26): coi kết quả tổng quát của khảo sát. Role: MANAGER, CREATOR.</li><li><strong>Generate Meeting Link</strong> (3.6.27): tự động tạo link Google Meet. Role: CREATOR.</li><li>Form Creator (theo sơ đồ): công cụ tạo câu hỏi (Questions) với time slot (0:10, 15:20, 21:30...), có preview.</li></ul><h2 id="_4-approval-sequence-fr-3-6-9" tabindex="-1">4. Approval Sequence (FR 3.6.9) <a class="header-anchor" href="#_4-approval-sequence-fr-3-6-9" aria-label="Permalink to &quot;4. Approval Sequence (FR 3.6.9)&quot;">​</a></h2><p>BA được người dùng xác nhận 2026-10-18, thay thế quy tắc QC và các vòng duyệt lịch sử:</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>TODO --Creator được giao bấm Bắt đầu--&gt; IN_PROGRESS</span></span>
<span class="line"><span>IN_PROGRESS --lưu bài và Gửi duyệt--&gt; IN_REVIEW / MANAGER</span></span>
<span class="line"><span>  Manager approve:</span></span>
<span class="line"><span>    requiresClientApproval=false --&gt; FINISHED</span></span>
<span class="line"><span>    requiresClientApproval=true  --&gt; IN_REVIEW / CLIENT</span></span>
<span class="line"><span>  Client active bất kỳ approve --&gt; FINISHED</span></span>
<span class="line"><span>  Manager hoặc Client reject có lý do --&gt; IN_PROGRESS</span></span>
<span class="line"><span>  Creator withdraw trước Manager decision --&gt; IN_PROGRESS</span></span></code></pre></div><ul><li>POST tích hợp trước qua /editor, liên kết tối đa một Post cùng Workspace. Một bản nội dung hiện tại; khóa sửa khi review, không snapshot/diff các lượt cũ. Giữ content_version của Admin, không xây kho phiên bản mới.</li><li>Client cần duyệt nhưng chưa có Client có User active thì chặn gửi, báo Manager bổ sung. Nếu hết Client trong lúc chờ thì giữ bước, không tự skip. Client mới được thêm có thể duyệt.</li><li>Chỉ một Client bất kỳ quyết định; decision hợp lệ đầu tiên thắng. Không yêu cầu toàn bộ Client hoặc gán đại diện.</li><li>Thu hồi chỉ cho assignee Creator trước Manager decision; không thu hồi khi chờ Client. Reject/withdraw không mở quyền sửa brief/deadline/giao lại cho Manager.</li><li>Submit lại sau reject/withdraw tạo lượt mới từ Manager; approval cũ chỉ là audit, không còn hiệu lực cho nội dung mới.</li><li>task_approvals giữ APPROVE/REJECT theo từng lượt/bước, tối đa hai decision/lượt; nhận xét duyệt khác task_comments. Không tạo sẵn dòng decision hoặc collection round riêng.</li><li>IN_REVIEW giữ bước MANAGER/CLIENT riêng; ngoài IN_REVIEW reviewStep=null. Cancel đóng lượt chờ; FINISHED không mở lại, không tự publish.</li><li>In-app báo người duyệt tiếp theo và Creator khi reject, không email. Quyền kiểm theo Workspace và User active; Owner Agency không tự có quyền Manager.</li><li>Các loại Task khác chỉ chuẩn bị contract, tích hợp nội dung theo chủ module sau. Không thay Yjs/editor chuyên biệt, publishing hoặc Admin moderation của thành viên khác.</li></ul><p>Chi tiết AC, API, chống xung đột và kế hoạch 6 giai đoạn: <a href="./../feature/content-task-workflow/3-6-9-approval-sequence-creator-manager-client/spec.html">FR3.6.9</a>. API/POST integration/UI đã kiểm thử cô lập; rollout vẫn tắt, Atlas APPLY và SQL/inbox/Gateway end-to-end còn chờ giai đoạn 6/phối hợp chủ publish.</p><h2 id="_5-cac-view-ho-tro-task-fr-3-6-4-–-3-6-8" tabindex="-1">5. Các View hỗ trợ Task (FR 3.6.4 – 3.6.8) <a class="header-anchor" href="#_5-cac-view-ho-tro-task-fr-3-6-4-–-3-6-8" aria-label="Permalink to &quot;5. Các View hỗ trợ Task (FR 3.6.4 – 3.6.8)&quot;">​</a></h2><p>Dùng chung cho tất cả loại Task, tham khảo cách làm của Jira để đảm bảo chi tiết:</p><table tabindex="0"><thead><tr><th>FR</th><th>View</th><th>Mô tả</th></tr></thead><tbody><tr><td>3.6.4</td><td>List Task View</td><td>Coi list task kiểu Jira</td></tr><tr><td>3.6.5</td><td>Calendar Task View</td><td>Kiểu Google Calendar, kéo thả được</td></tr><tr><td>3.6.6</td><td>Gantt Timeline Task View</td><td>Kiểu waterfall tiến trình công việc</td></tr><tr><td>3.6.7</td><td>Kanban Board Task View</td><td>Board kéo thả trạng thái (làm thêm 3 kiểu board khác nhau)</td></tr><tr><td>3.6.8</td><td>View Task Filter</td><td>Filter/sort/search theo toàn bộ field dữ liệu, tham khảo Jira</td></tr></tbody></table><p>Role toàn bộ: CREATOR, CLIENT, MANAGER.</p><h2 id="_6-content-writing-fr-3-6-10" tabindex="-1">6. Content Writing (FR 3.6.10) <a class="header-anchor" href="#_6-content-writing-fr-3-6-10" aria-label="Permalink to &quot;6. Content Writing (FR 3.6.10)&quot;">​</a></h2><ul><li>Dựa trên công nghệ viết chữ vector giống Google Docs.</li><li><strong>Tự động chuyển font chữ đúng chuẩn khi đăng bài</strong> — giải quyết pain point hiện tại của người làm content phải copy phần font chữ muốn đổi qua công cụ ngoài (ví dụ Unikey/Yantext) trước khi đăng.</li><li>Có <strong>Content History/Version</strong>: xem ai chỉnh sửa phần nào, khôi phục lại các version trước đó nếu cần.</li><li><strong>[CONFIRMED 2026-09-17]</strong> Role sửa nội dung trực tiếp: <strong>CREATOR và MANAGER</strong> đều sửa được field content trực tiếp (không chỉ Creator) — Manager có thể cần override sửa gấp khi Creator không online hoặc chỉnh nhỏ không cần giao lại việc. Content History (trên) ghi rõ ai sửa phần nào để không mất minh bạch khi có nhiều người cùng sửa. Client vẫn chỉ dừng ở mức Add Comment (mục 2) — không sửa trực tiếp nội dung.</li><li>Role: CREATOR, MANAGER.</li></ul><h2 id="_7-material-brand-resources-fr-3-6-11-–-3-6-17" tabindex="-1">7. Material &amp; Brand Resources (FR 3.6.11 – 3.6.17) <a class="header-anchor" href="#_7-material-brand-resources-fr-3-6-11-–-3-6-17" aria-label="Permalink to &quot;7. Material &amp; Brand Resources (FR 3.6.11 – 3.6.17)&quot;">​</a></h2><h3 id="material-repository-3-6-11-–-3-6-14" tabindex="-1">Material Repository (3.6.11 – 3.6.14) <a class="header-anchor" href="#material-repository-3-6-11-–-3-6-14" aria-label="Permalink to &quot;Material Repository (3.6.11 – 3.6.14)&quot;">​</a></h3><ul><li>Kho ảnh của người chụp ảnh/editor.</li><li>Phân loại theo dạng <strong>raw</strong> hoặc <strong>đã retouched</strong>.</li><li>Cảnh báo nếu dùng ảnh raw (chưa xử lý) khi đăng.</li><li><strong>Brand Asset Upload for Reference</strong>: tài liệu do CLIENT cung cấp để Creator tham khảo khi sáng tạo — khác biệt với Material Repository (Material là sản phẩm do Creator/photographer tạo ra; Brand Collection là input Client cung cấp).</li><li>Add/Update/Remove Material Repository (3.6.12 – 3.6.14): CRUD chuẩn.</li><li>Role: CREATOR, CLIENT.</li></ul><h3 id="watermark-download-3-6-15-–-3-6-16" tabindex="-1">Watermark &amp; Download (3.6.15 – 3.6.16) <a class="header-anchor" href="#watermark-download-3-6-15-–-3-6-16" aria-label="Permalink to &quot;Watermark &amp; Download (3.6.15 – 3.6.16)&quot;">​</a></h3><ul><li><strong>Apply Watermark</strong> (3.6.15): tương tự công cụ img2go watermark — sau khi ảnh/ấn phẩm đã qua chỉnh sửa, Creator thêm watermark thương hiệu (logo do Client cung cấp) để đánh dấu bản quyền ấn phẩm. Role: CREATOR.</li><li><strong>Download Material</strong> (3.6.16): mọi role download tài liệu từ workspace về máy local để lưu trữ hoặc chỉnh sửa. Role: CREATOR, CLIENT, MANAGER.</li></ul><h3 id="hashtag-collection-3-6-17-–-3-6-21" tabindex="-1">Hashtag Collection (3.6.17 – 3.6.21) <a class="header-anchor" href="#hashtag-collection-3-6-17-–-3-6-21" aria-label="Permalink to &quot;Hashtag Collection (3.6.17 – 3.6.21)&quot;">​</a></h3><ul><li><strong>Apply Hashtag</strong> (3.6.17): thêm 1 hoặc nhiều hashtag cho bài đăng/sự kiện/chiến dịch. Role: CREATOR, CLIENT.</li><li><strong>View Hashtag Collection</strong> (3.6.18): kho hashtag riêng cho từng Workspace. Creator tự thêm tự do; Client thêm mang tính đặc thù, bắt buộc dùng cho sự kiện của họ; AI recommend thêm hashtag phù hợp. Role: CREATOR, CLIENT.</li><li><strong>Add Hashtag Collection</strong> (3.6.19): thêm hashtag, có phân loại rõ mục đích sử dụng. Role: CREATOR, CLIENT.</li><li><strong>Update Hashtag Collection</strong> (3.6.20): cập nhật hashtag. Role: CREATOR, CLIENT.</li><li><strong>Remove Hashtag Collection</strong> (3.6.21): xóa hashtag cũ — <strong>soft delete</strong>, hashtag đã áp dụng vào bài cũ không bị xóa theo. Role: CREATOR, CLIENT.</li></ul><h2 id="_8-compliance-copyright-fr-3-6-33-–-3-6-35" tabindex="-1">8. Compliance &amp; Copyright (FR 3.6.33 – 3.6.35) <a class="header-anchor" href="#_8-compliance-copyright-fr-3-6-33-–-3-6-35" aria-label="Permalink to &quot;8. Compliance &amp; Copyright (FR 3.6.33 – 3.6.35)&quot;">​</a></h2><ul><li><strong>Check Compliance Content</strong> (3.6.33): check đạo văn, bạo lực, hình ảnh dung tục. Dùng API kéo về để có kết quả chuẩn nhất, trả về bảng phân tích từ ngữ + đoạn không đúng chuẩn — giúp Creator hiểu và tự fix trước khi vi phạm chính sách nền tảng hoặc mất khả năng lên trending. Role: CREATOR, CLIENT.</li><li><strong>Check Copyright Infringement</strong> (3.6.34): check bản quyền hình ảnh, thương hiệu. <strong>[CONFIRMED 2026-09-17]</strong> Dùng API bên thứ 3 (reverse image search — ví dụ Google Vision API / TinEye hoặc tương đương) để đối chiếu ảnh đầu ra với nguồn ảnh có sẵn trên Internet, giống cách Check Compliance Content (3.6.33) đã dùng API ngoài để có kết quả chuẩn. Trả về cảnh báo nếu phát hiện ảnh trùng khớp nguồn có bản quyền, để Creator tự thay ảnh trước khi đăng. Role: CREATOR, CLIENT.</li><li><strong>View Content History</strong> (3.6.35): không trừ credit AI khi user tái sử dụng tài nguyên đã tạo trước đó. Role: CREATOR, CLIENT, MANAGER.</li></ul><h2 id="_9-mail-template-fr-3-6-28-–-3-6-32" tabindex="-1">9. Mail Template (FR 3.6.28 – 3.6.32) <a class="header-anchor" href="#_9-mail-template-fr-3-6-28-–-3-6-32" aria-label="Permalink to &quot;9. Mail Template (FR 3.6.28 – 3.6.32)&quot;">​</a></h2><ul><li>View/Create/Update/Delete Mail Template, Send Email via Template — CRUD chuẩn cho mẫu email + gửi email thực tế.</li><li><strong>[CẬP NHẬT 2026-10-12 — thay thế quyết định 2026-09-17]</strong> Mail Template <strong>thuộc Workspace</strong> (không phải mẫu cá nhân của mọi user). Role dùng: OWNER, MANAGER, CREATOR; CLIENT không. Gửi nhiều người (dán/CSV), async qua hàng đợi, giới hạn theo chuẩn Gmail (450/ngày hệ thống, 100/ngày/Workspace, 200/lần), hẹn giờ, tệp đính kèm, unsubscribe + suppression theo Workspace. Admin quản trị thư viện mẫu hệ thống và dùng làm mẫu cho Broadcast 3.10.1. Chi tiết: <code>feature/content-task-workflow/3-6-32-send-email-via-template/plan.md</code> (cùng bộ với các FR <code>3-6-28</code> đến <code>3-6-31</code>, mỗi FR có đủ spec, plan, task, test).</li></ul><h2 id="_10-tham-chieu-media-platform-post-chi-tiet-trong-so-đo" tabindex="-1">10. Tham chiếu Media Platform Post (chi tiết trong sơ đồ) <a class="header-anchor" href="#_10-tham-chieu-media-platform-post-chi-tiet-trong-so-đo" aria-label="Permalink to &quot;10. Tham chiếu Media Platform Post (chi tiết trong sơ đồ)&quot;">​</a></h2><p>Theo sơ đồ Flow diagram, khu vực &quot;Media Platform Post&quot; gồm các module con: Create Form, Export File, Apply Watermark, Content Writing View, Preview Post, content, hashtag — đây chính là workspace/editor tổng hợp để tạo ra 1 đơn vị content hoàn chỉnh (loại Post ở mục 3) trước khi đưa vào Approval Sequence (mục 4) rồi Publish (xem <a href="./07-publishing-social-collaborator.html">07-publishing-social-collaborator.md</a>).</p>`,50)])])}const m=n(o,[["render",h]]);export{d as __pageData,m as default};
